files.apps/web/src/frontend/features/billing/p:
import { RemainingBalance } from "./remaining-balance";
import type { Plan, Balance } from "./types";

export function PricingTable({ plan, balance }: { plan: Plan; balance: Balance }) {
  return (
    <section className="rounded-lg border p-4">
      <h2 className="text-lg font-medium">Plan: {plan.name}</h2>
      <RemainingBalance balance={balance} />
      <a className="btn" href="/settings/subscription/top-up">Top up</a>
    </section>
  );
}

files.apps/web/src/frontend/features/billing/r:
import { formatUsd } from "@acme/ui/format";
import type { Balance } from "./types";

export function RemainingBalance({ balance }: { balance: Balance }) {
  return <p className="text-sm">Balance: {formatUsd(balance.remaining)}</p>;
}

files.apps/expo/src/features/billing/usage-bar:
import { Text, View } from "react-native";
import { formatUsd } from "@acme/ui/format";

export function UsageBar({ plan, balance, used }: UsageBarProps) {
  return (
    <View style={styles.card}>
      <Text style={styles.plan}>{plan.name}</Text>
      <Text style={styles.balance}>Balance: {formatUsd(balance.remaining)}</Text>
      <Meter value={used} />
    </View>
  );
}

